                             ^
error: expect(received).toBe(expected)
```

While I understand that obfuscating what's happening might not be optimal for some use cases I'm wondering if it makes sense to make this body parsing safe to consumers and instead have a more explicit parsing method that keeps this behaviour.

Relevant part of the framework's `request.ts`:
https://github.com/honojs/hono/blob/main/src/request.ts#L208-L227

```ts
  private cachedBody = (key: keyof Body) => {
    const { bodyCache, raw } = this
    const cachedBody = bodyCache[key]

    if (cachedBody) {
      return cachedBody
    }

    const anyCachedKey = Object.keys(bodyCache)[0]
    if (anyCachedKey) {
      return (bodyCache[anyCachedKey as keyof Body] as Promise<BodyInit>).then((body) => {
        if (anyCachedKey === 'json') {
          body = JSON.stringify(body)
        }
        return new Response(body)[key]()
      })
    }

    return (bodyCache[key] = raw[key]())
  }
```
 
 Happy to give it a go at a PR if this is an acceptable change and/or happy to further discuss this.

### What version of Hono are you using?

4.5.1

### What runtime/platform is your app running on?

Cloudflare workers

### What steps can reproduce the bug?

There is a bit of a discussion on stack overflow about application/json content-type - if it's valid for it to indicate a charset or not (https://stackoverflow.com/questions/9254891/what-does-content-type-application-json-charset-utf-8-really-mean).

I noticed that `context.json()` returns a response with content-type with a charset included (https://github.com/honojs/hono/blob/main/src/context.ts#L733), but when we send a request with the exact content-type to the app which uses a validator, it fails. It seems to be caused by https://github.com/honojs/hono/blob/main/src/validator/validator.ts#L74 and the fact that `jsonRegex` doesn't include optional matching for a charset.

I prepared a code that demonstrates the issue and a test case.

File app.ts:
```
import { createRoute, OpenAPIHono, z } from '@hono/zod-openapi';

const app = new OpenAPIHono();

const RequestBodySchema = z
  .object({
    name: z.string(),
  })
  .openapi('RequestBody');

const ResponseBodySchema = z
  .object({
    status: z.string(),
  })
  .openapi('ResponseBody');

const route = createRoute({
  method: 'post',
  path: '/test',
  request: {
    body: {
      content: {
        'application/json': {
          schema: RequestBodySchema,
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      content: {
        'application/json': {
          schema: ResponseBodySchema,
        },
      },
      description: 'Successful response',
    },
  },
});

app.openapi(route, async (c) => {
  const { name } = c.req.valid('json');
  return c.json({
    status: 'ok',
  } satisfies z.infer<typeof ResponseBodySchema>);
});

export default app;

```

file app.test.ts:
```
import { describe, expect, test } from 'vitest';
import app from './app';

test('should return valid response for content-type application/json with a charset', async () => {
  const res = await app.request('/test', {
    method: 'post',
    body: JSON.stringify({
      name: 'John Doe',
    }),
    headers: {
      'content-type': 'application/json; charset=utf-8',
    },
  });
  console.log(await res.text());
  expect(res.status).toBe(200);
});
```



### What is the expected behavior?

I would expect the test to pass. Validator should accept both 'application/json' as well as 'application/json; charset=utf-8'

### What do you see instead?

Error - zod parsing fails, because it's called on empty object and the requests fails with status 400.

### Additional information

_No response_

### What version of Hono are you using?

3.11.11

### What runtime/platform is your app running on?

Vercel

### What steps can reproduce the bug?

```ts
// app/api/[[...route]]/route.ts

import { Hono } from "hono";
import { cors } from "hono/cors";
import { handle } from "hono/vercel";

export const runtime = "edge";

const app = new Hono().basePath("/api");

app.use("*", cors());

app.post("/test", async (c) => {
  const body = await c.req.json();
  return c.json({ ok: true, body });
});

export const POST = handle(app);
```

```ts
// Client

const res = await fetch("http://localhost:3001/api/test", {
  method: "POST",
  headers: { "Content-Type": "application/json", },
  body: JSON.stringify({ hello: "world" }),
});

// ❌ Error: CORS error
```

```ts
// Client

const res = await fetch("http://localhost:3001/api/test", {
  method: "POST",
  body: JSON.stringify({ hello: "world" }),
});

// ✅ It works
```

---

However, when using `zValidator` from `@hono/zod-validator`, I experience this:

```ts
import { zValidator } from "@hono/zod-validator";
import { Hono } from "hono";
import { cors } from "hono/cors";
import { handle } from "hono/vercel";
import { z } from "zod";

export const runtime = "edge";

const app = new Hono().basePath("/api");

app.use("*", cors());

const schema = z.object({
  hello: z.string(),
});

app.post("/test", zValidator("json", schema), async (c) => {
  const body = await c.req.valid("json");
  return c.json({ ok: true, body });
});

export const POST = handle(app);

```

```ts
// Client

const res = await fetch("http://localhost:3001/api/test", {
  method: "POST",
  body: JSON.stringify({ hello: "world" }),
});

// ❌ Error: 400 Bad Request
// { success: false, message: "Invalid HTTP header: Content-Type=text/plain;charset=UTF-8" }
```

```ts
// Client

const res = await fetch("http://localhost:3001/api/test", {
  method: "POST",
  headers: { "Content-Type": "application/json", },
  body: JSON.stringify({ hello: "world" }),
});

// ❌ Error: CORS error
```

### What is the expected behavior?

I should get CORS to work when passing `Content-Type: application/json` from the client.

### What do you see instead?

_No response_

### Additional information

Dependencies:

```
"@hono/zod-validator": "^0.1.11",
"hono": "^3.11.11",
"next": "14.0.4",
"react": "^18",
"react-dom": "^18",
"zod": "^3.22.4",
```
